import React, { useEffect, useMemo, useState } from 'react'
import {
  addCtaParty,
  addCtaSlot,
  ctaAttendanceStatuses,
  ctaClassifications,
  createCtaSheet,
  duplicateCtaSlot,
  deleteCtaParty,
  deleteCtaSignup,
  deleteCtaSlot,
  loadCtaWorkspace,
  loadPublicCtaSheet,
  regenerateCtaShareToken,
  saveCtaTemplate,
  submitPublicCtaAction,
  swapCtaSlots,
  updateCtaParty,
  updateCtaSheet,
  updateCtaSignup,
  updateCtaSlot,
} from './lib/ctaData'

const icons = {
  plus: <><path d="M12 5v14M5 12h14" /></>,
  edit: <><path d="m4 16.5-.8 3.3 3.3-.8L18.8 6.7a2.1 2.1 0 0 0-3-3L4 16.5Z" /><path d="m14.5 5.5 3 3" /></>,
  trash: <><path d="M4 7h16M10 11v6M14 11v6M6 7l1 14h10l1-14M9 7V4h6v3" /></>,
  copy: <><rect x="8" y="8" width="12" height="12" rx="2" /><path d="M16 8V6a2 2 0 0 0-2-2H6a2 2 0 0 0-2 2v8a2 2 0 0 0 2 2h2" /></>,
  box: <><path d="m21 8-9-5-9 5 9 5 9-5Z" /><path d="m3 8 9 5 9-5M3 8v8l9 5 9-5V8M12 13v8" /></>,
  check: <path d="m5 12 4 4L19 6" />,
  arrow: <><path d="M5 12h14M13 6l6 6-6 6" /></>,
  close: <><path d="M6 6l12 12M18 6 6 18" /></>,
  search: <><circle cx="11" cy="11" r="7" /><path d="m20 20-4-4" /></>,
  refresh: <><path d="M20 11a8 8 0 0 0-14.7-4L4 9" /><path d="M4 4v5h5M4 13a8 8 0 0 0 14.7 4L20 15" /><path d="M20 20v-5h-5" /></>,
  filter: <><path d="M4 6h16M7 12h10M10 18h4" /></>,
}

const publicCtaOrigin = String(import.meta.env.VITE_PUBLIC_APP_URL || 'https://albion-regear.vercel.app').replace(/\/+$/, '')
const gearFields = [['weapon', 'Weapon'], ['offHand', 'Off-hand'], ['helmet', 'Head'], ['armor', 'Armor'], ['boots', 'Boots'], ['cape', 'Cape'], ['food', 'Food'], ['potion', 'Potion']]

function CtaIcon({ name, size = 16 }) { return <svg className="icon" width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.7" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">{icons[name]}</svg> }
function CtaModal({ title, eyebrow, children, onClose, wide = false }) { return <div className="modal-backdrop" onMouseDown={(event) => event.target === event.currentTarget && onClose()}><div className={`modal cta-modal ${wide ? 'cta-modal-wide' : ''}`}><div className="modal-heading"><div><span className="eyebrow">{eyebrow}</span><h2>{title}</h2></div><button type="button" className="close-button" onClick={onClose} aria-label="Close"><CtaIcon name="close" size={18} /></button></div>{children}</div></div> }
function ctaDayKey(value) { const date = new Date(value); return Number.isNaN(date.getTime()) ? '' : `${date.getUTCFullYear()}-${String(date.getUTCMonth() + 1).padStart(2, '0')}-${String(date.getUTCDate()).padStart(2, '0')}` }
function ctaDateTimeParts(value) { const date = new Date(value); if (Number.isNaN(date.getTime())) return { date: ctaDayKey(new Date()), time: '20:00' }; return { date: ctaDayKey(date), time: `${String(date.getUTCHours()).padStart(2, '0')}:${String(date.getUTCMinutes()).padStart(2, '0')}` } }
function ctaStartsAt(date, time) { return new Date(`${date}T${time}:00Z`).toISOString() }
function ctaUtcLabel(value) { const date = new Date(value); return Number.isNaN(date.getTime()) ? 'UTC time not set' : `${new Intl.DateTimeFormat('en-GB', { timeZone: 'UTC', weekday: 'short', day: '2-digit', month: 'short', year: 'numeric', hour: '2-digit', minute: '2-digit', hour12: false }).format(date)} UTC` }
function ctaAttendanceLabel(value) { return String(value || 'signed_up').replace('_', ' ').replace(/\b\w/g, (letter) => letter.toUpperCase()) }
function formatActivityTime(value) { const date = new Date(value); return Number.isNaN(date.getTime()) ? 'Earlier' : `${new Intl.DateTimeFormat('en-GB', { timeZone: 'UTC', day: '2-digit', month: 'short', hour: '2-digit', minute: '2-digit', hour12: false }).format(date)} UTC` }
function CtaStatus({ status }) { return <span className={`cta-sheet-status-pill status-${status}`}>{status === 'locked' ? 'Locked' : status === 'open' ? 'Open' : 'Draft'}</span> }
function buildSlotDraft(slot, field, value) { return { slotNumber: field === 'slotNumber' ? Number(value || 1) : slot.slotNumber, classification: field === 'classification' ? value : slot.classification, roleLabel: field === 'roleLabel' ? value.trim() || slot.classification : slot.roleLabel, weapon: field === 'weapon' ? value.trim() : slot.weapon, offHand: field === 'offHand' ? value.trim() : slot.offHand, helmet: field === 'helmet' ? value.trim() : slot.helmet, armor: field === 'armor' ? value.trim() : slot.armor, boots: field === 'boots' ? value.trim() : slot.boots, cape: field === 'cape' ? value.trim() : slot.cape, food: field === 'food' ? value.trim() : slot.food, potion: field === 'potion' ? value.trim() : slot.potion, notes: field === 'notes' ? value.trim() : slot.notes } }
function ctaClassificationKey(value) { const key = String(value || 'dps').toLowerCase().replace(/[^a-z0-9]+/g, '-'); return key === 'bomb' ? 'dps' : key }
function ctaRowClass(slot, extra = '') { return ['cta-grid-row', `cta-grid-row-${ctaClassificationKey(slot.classification)}`, slot.signup ? 'filled' : 'open', extra].filter(Boolean).join(' ') }

function CtaPageIntro({ onNew }) { return <div className="cta-sheet-page-intro"><div><span className="eyebrow">Coup De Grace · CTA operations</span><h1>Composition sheets</h1><p>Build the roster once, then let members claim the exact role they want.</p></div><button type="button" className="button button-primary" onClick={onNew}><CtaIcon name="plus" size={16} />New sheet</button></div> }

export function CtaSheetsPage({ guild, session, onNotify }) {
  const [workspace, setWorkspace] = useState({ sheets: [], activity: [], templates: [] }); const [selectedId, setSelectedId] = useState(''); const [loading, setLoading] = useState(true); const [error, setError] = useState(''); const [createOpen, setCreateOpen] = useState(false); const [shareLinks, setShareLinks] = useState({})
  const admin = { id: session?.user?.id, username: session?.user?.user_metadata?.username, email: session?.user?.email }
  const refresh = async (focusId = '') => { if (!guild?.id) return; try { const next = await loadCtaWorkspace(guild.id); setWorkspace(next); setSelectedId((current) => focusId || current || next.sheets[0]?.id || ''); setError('') } catch (loadError) { setError(loadError.message || 'Could not load CTA sheets.') } }
  useEffect(() => { let mounted = true; setLoading(true); loadCtaWorkspace(guild?.id).then((next) => { if (mounted) { setWorkspace(next); setSelectedId(next.sheets[0]?.id || ''); setError('') } }).catch((loadError) => { if (mounted) setError(loadError.message || 'Could not load CTA sheets.') }).finally(() => { if (mounted) setLoading(false) }); return () => { mounted = false } }, [guild?.id])
  const selected = workspace.sheets.find((sheet) => sheet.id === selectedId) || workspace.sheets[0]
  const selectedSlotSignature = selected?.parties.flatMap((party) => party.slots).map((slot) => `${slot.id}:${slot.slotNumber}`).join('|') || ''
  useEffect(() => {
    if (!selected?.id || !guild?.id || selected.status === 'locked' || typeof document === 'undefined') return undefined
    const page = document.querySelector('.cta-workbook-page')
    if (!page) return undefined
    let draggedSlotId = ''
    const clearDragState = () => {
      draggedSlotId = ''
      page.querySelectorAll('.cta-grid-row').forEach((row) => row.classList.remove('dragging', 'drag-over'))
    }
    const findSlot = (slotId) => selected.parties.flatMap((party) => party.slots).find((slot) => slot.id === slotId)
    const findRowSlot = (targetRow) => {
      let currentParty = null
      for (const row of page.querySelectorAll('.cta-data-grid tbody tr')) {
        if (row.classList.contains('cta-party-row')) {
          const partyName = row.querySelector('strong')?.textContent?.trim()
          currentParty = selected.parties.find((party) => party.name === partyName) || null
          continue
        }
        if (row !== targetRow || !currentParty) continue
        const slotNumber = row.querySelector('.sticky-col-1 button')?.textContent?.trim()
        return currentParty.slots.find((slot) => String(slot.slotNumber) === slotNumber) || null
      }
      return null
    }
    const markRowsDraggable = () => page.querySelectorAll('.cta-grid-row').forEach((row) => { row.draggable = true })
    const onDragStart = (event) => {
      const row = event.target.closest?.('.cta-grid-row')
      const slot = row && findRowSlot(row)
      if (!slot) return
      draggedSlotId = slot.id
      row.classList.add('dragging')
      event.dataTransfer.effectAllowed = 'move'
      event.dataTransfer.setData('text/plain', slot.id)
    }
    const onDragOver = (event) => {
      const row = event.target.closest?.('.cta-grid-row')
      const targetSlot = row && findRowSlot(row)
      const sourceSlot = findSlot(draggedSlotId)
      if (!row || !targetSlot || !sourceSlot || sourceSlot.id === targetSlot.id || sourceSlot.partyId !== targetSlot.partyId) return
      event.preventDefault()
      page.querySelectorAll('.cta-grid-row.drag-over').forEach((candidate) => candidate.classList.remove('drag-over'))
      row.classList.add('drag-over')
    }
    const onDrop = async (event) => {
      const row = event.target.closest?.('.cta-grid-row')
      const targetSlot = row && findRowSlot(row)
      const sourceId = event.dataTransfer.getData('text/plain') || draggedSlotId
      const sourceSlot = findSlot(sourceId)
      if (!row || !targetSlot || !sourceSlot || sourceSlot.id === targetSlot.id || sourceSlot.partyId !== targetSlot.partyId) return clearDragState()
      event.preventDefault()
      try {
        await swapCtaSlots(guild.id, selected.id, sourceSlot, targetSlot, admin)
        await refresh(selected.id)
        onNotify?.('Slots reordered')
      } catch (error) {
        onNotify?.(error.message || 'Could not reorder the slots.')
      } finally {
        clearDragState()
      }
    }
    const onDragEnd = clearDragState
    const observer = new MutationObserver(markRowsDraggable)
    page.addEventListener('dragstart', onDragStart)
    page.addEventListener('dragover', onDragOver)
    page.addEventListener('drop', onDrop)
    page.addEventListener('dragend', onDragEnd)
    observer.observe(page, { childList: true, subtree: true })
    markRowsDraggable()
    return () => {
      observer.disconnect()
      page.querySelectorAll('.cta-grid-row').forEach((row) => { row.draggable = false })
      page.removeEventListener('dragstart', onDragStart)
      page.removeEventListener('dragover', onDragOver)
      page.removeEventListener('drop', onDrop)
      page.removeEventListener('dragend', onDragEnd)
    }
  }, [selected?.id, selected?.status, selectedSlotSignature, guild?.id, loading])
  useEffect(() => {
    if (!selected?.id || !guild?.id || selected.status === 'locked' || typeof document === 'undefined') return undefined
    const toolbar = document.querySelector('.cta-workbook-page .cta-party-action-bar')
    if (!toolbar) return undefined
    const rows = selected.parties.flatMap((party) => party.slots.map((slot) => ({ party, slot })))
    const rowField = document.createElement('label')
    rowField.className = 'cta-row-duplicate-field'
    rowField.append('Row')
    const rowSelect = document.createElement('select')
    rowSelect.setAttribute('aria-label', 'Choose row to duplicate')
    const emptyOption = document.createElement('option')
    emptyOption.value = ''
    emptyOption.textContent = rows.length ? 'Choose row' : 'No rows available'
    rowSelect.append(emptyOption)
    rows.forEach(({ party, slot }) => {
      const option = document.createElement('option')
      option.value = slot.id
      option.textContent = `${party.name} / Slot ${slot.slotNumber} / ${slot.roleLabel || slot.classification}`
      rowSelect.append(option)
    })
    rowField.append(rowSelect)
    const duplicateButton = document.createElement('button')
    duplicateButton.type = 'button'
    duplicateButton.className = 'button button-ghost table-duplicate-button'
    duplicateButton.textContent = 'Duplicate row'
    duplicateButton.disabled = true
    duplicateButton.title = 'Copy the selected row into a new slot'
    const onSelectionChange = () => { duplicateButton.disabled = !rowSelect.value }
    const onDuplicate = async () => {
      const selectedRow = rows.find(({ slot }) => slot.id === rowSelect.value)
      if (!selectedRow) return
      duplicateButton.disabled = true
      duplicateButton.textContent = 'Duplicating...'
      try {
        await duplicateCtaSlot(guild.id, selected.id, selectedRow.slot, admin)
        await refresh(selected.id)
        onNotify?.('Row duplicated')
      } catch (error) {
        onNotify?.(error.message || 'Could not duplicate the row.')
      } finally {
        duplicateButton.textContent = 'Duplicate row'
        duplicateButton.disabled = !rowSelect.value
      }
    }
    rowSelect.addEventListener('change', onSelectionChange)
    duplicateButton.addEventListener('click', onDuplicate)
    toolbar.append(rowField, duplicateButton)
    return () => {
      rowSelect.removeEventListener('change', onSelectionChange)
      duplicateButton.removeEventListener('click', onDuplicate)
      rowField.remove()
      duplicateButton.remove()
    }
  }, [selected?.id, selected?.status, selectedSlotSignature, guild?.id, loading])
  const run = async (operation, message, focusId = selected?.id) => { try { await operation(); await refresh(focusId); onNotify?.(message) } catch (actionError) { onNotify?.(actionError.message || 'Could not save CTA sheet changes.') } }
  const copyLayout = async (targetId, layout) => { for (const [partyIndex, party] of layout.entries()) { const targetParty = partyIndex === 0 ? targetId.party : await addCtaParty(guild.id, targetId.sheet.id, party.name, admin); for (const slot of party.slots || []) await addCtaSlot(guild.id, targetId.sheet.id, targetParty.id, slot, admin) } }
  const create = async (draft) => { try { const result = await createCtaSheet(guild.id, draft, admin); const source = draft.startMode === 'copy' ? workspace.sheets.find((sheet) => sheet.id === draft.sourceSheetId) : workspace.templates.find((template) => template.id === draft.templateId); const layout = draft.startMode === 'template' ? source?.template_data?.parties || [] : source?.parties || []; if (layout.length) await copyLayout(result, layout); setShareLinks((current) => ({ ...current, [result.sheet.id]: `${publicCtaOrigin}/cta/${result.shareToken}` })); setCreateOpen(false); await refresh(result.sheet.id); onNotify?.(`${draft.name} created`) } catch (actionError) { onNotify?.(actionError.message || 'Could not create the CTA sheet.') } }
  const regenerate = async () => { try { const result = await regenerateCtaShareToken(selected.id, session?.access_token); setShareLinks((current) => ({ ...current, [selected.id]: result.url })); onNotify?.('Public CTA link regenerated') } catch (actionError) { onNotify?.(actionError.message || 'Could not regenerate the public link.') } }
  const copyLink = async () => { const url = shareLinks[selected?.id]; if (!url) { onNotify?.('Regenerate the public link first to reveal it'); return } try { await navigator.clipboard.writeText(url); onNotify?.('Public CTA link copied') } catch { onNotify?.(url) } }
  const duplicate = async () => { if (!selected) return; const draft = { ctaName: selected.ctaName, name: `${selected.name} copy`, startsAt: selected.startsAt, status: 'draft', disarrayLevel: selected.disarrayLevel, recommendedGroupSize: selected.recommendedGroupSize, initialPartyName: selected.parties[0]?.name || 'Party 1' }; try { const result = await createCtaSheet(guild.id, draft, admin); await copyLayout(result, selected.parties); setShareLinks((current) => ({ ...current, [result.sheet.id]: `${publicCtaOrigin}/cta/${result.shareToken}` })); await refresh(result.sheet.id); onNotify?.(`${selected.name} duplicated`) } catch (actionError) { onNotify?.(actionError.message || 'Could not duplicate the sheet.') } }
  const saveTemplate = async () => { const templateName = window.prompt('Template name', `${selected?.name || 'CTA'} template`); if (templateName?.trim() && selected) await run(() => saveCtaTemplate(guild.id, templateName, `Saved from ${selected.ctaName}`, selected, admin), 'Template saved') }
  if (loading) return <div className="page"><div className="cta-workbook-loading"><div className="public-loader" /><span>Loading composition sheets...</span></div></div>
  if (error) return <div className="page"><CtaPageIntro onNew={() => setCreateOpen(true)} /><section className="panel cta-setup-error"><strong>CTA Sheets need one database migration.</strong><p>{error}</p><small>Run <code>supabase/cta_composition_sheets.sql</code> in Supabase, then refresh.</small><button type="button" className="button button-primary" onClick={() => refresh()}>Refresh sheets</button></section>{createOpen && <CtaSheetCreateWizard sheets={workspace.sheets} templates={workspace.templates} onClose={() => setCreateOpen(false)} onSave={create} />}</div>
  return <div className="page cta-workbook-page"><CtaPageIntro onNew={() => setCreateOpen(true)} /><section className="cta-workbook"><div className="cta-workbook-header"><div className="cta-workbook-title"><span className="eyebrow">CTA workbook</span><strong>{workspace.sheets.length} sheets</strong></div><button type="button" className="icon-button" onClick={() => refresh()} aria-label="Refresh composition sheets" title="Refresh composition sheets"><CtaIcon name="refresh" size={16} /></button></div><div className="cta-sheet-tabs" role="tablist" aria-label="CTA composition sheets">{workspace.sheets.map((sheet) => <button type="button" role="tab" aria-selected={selected?.id === sheet.id} className={`cta-sheet-tab ${selected?.id === sheet.id ? 'selected' : ''}`} key={sheet.id} onClick={() => setSelectedId(sheet.id)}><span>{sheet.ctaName}</span><small>{sheet.name} · {ctaDateTimeParts(sheet.startsAt).date}</small><CtaStatus status={sheet.status} /></button>)}<button type="button" className="cta-sheet-tab cta-sheet-tab-add" onClick={() => setCreateOpen(true)}><CtaIcon name="plus" size={15} />New sheet</button></div>{selected ? <CtaSheetEditor sheet={selected} activity={workspace.activity.filter((entry) => entry.sheet_id === selected.id || entry.sheetId === selected.id)} shareUrl={shareLinks[selected.id]} onSave={(changes) => run(() => updateCtaSheet(guild.id, selected.id, changes, admin), 'CTA sheet updated')} onRegenerateLink={regenerate} onCopyLink={copyLink} onDuplicate={duplicate} onSaveTemplate={saveTemplate} onAddParty={(value) => run(() => addCtaParty(guild.id, selected.id, value, admin), 'Party added')} onRenameParty={(partyId, value) => run(() => updateCtaParty(guild.id, selected.id, partyId, value, admin), 'Party renamed')} onDeleteParty={(partyId) => run(() => deleteCtaParty(guild.id, selected.id, partyId, admin), 'Party removed')} onAddSlot={(partyId, draft) => run(() => addCtaSlot(guild.id, selected.id, partyId, draft, admin), 'Slot added')} onBulkAdd={(partyId, draft, count) => run(async () => { for (let index = 0; index < count; index += 1) await addCtaSlot(guild.id, selected.id, partyId, { ...draft, slotNumber: Number(draft.startNumber || 1) + index }, admin) }, `${count} slots added`)} onUpdateSlot={(slotId, draft) => run(() => updateCtaSlot(guild.id, selected.id, slotId, draft, admin), 'Slot updated')} onDeleteSlot={(slotId) => run(() => deleteCtaSlot(guild.id, selected.id, slotId, admin), 'Slot removed')} onUpdateSignup={(signupId, changes) => run(() => updateCtaSignup(guild.id, selected.id, signupId, changes, admin), 'Signup updated')} onDeleteSignup={(signupId) => run(() => deleteCtaSignup(guild.id, selected.id, signupId, admin), 'Signup removed')} /> : <div className="cta-workbook-empty"><CtaIcon name="box" size={25} /><h2>No composition sheets yet</h2><p>Create a blank workbook, duplicate an existing layout, or start from a saved template.</p><button type="button" className="button button-primary" onClick={() => setCreateOpen(true)}><CtaIcon name="plus" size={16} />Create first sheet</button></div>}</section>{createOpen && <CtaSheetCreateWizard sheets={workspace.sheets} templates={workspace.templates} onClose={() => setCreateOpen(false)} onSave={create} />}</div>
}

function CtaSheetCreateWizard({ onClose, onSave, sheets = [], templates = [] }) {
  const [step, setStep] = useState(1); const [ctaName, setCtaName] = useState(''); const [name, setName] = useState('Main composition'); const [date, setDate] = useState(ctaDayKey(new Date())); const [time, setTime] = useState('20:00'); const [party, setParty] = useState('Party 1'); const [status, setStatus] = useState('draft'); const [disarray, setDisarray] = useState(''); const [groupSize, setGroupSize] = useState(''); const [startMode, setStartMode] = useState('blank'); const [sourceSheetId, setSourceSheetId] = useState(sheets[0]?.id || ''); const [templateId, setTemplateId] = useState(templates[0]?.id || ''); const validTime = /^([01]\d|2[0-3]):[0-5]\d$/.test(time); const canContinue = ctaName.trim() && name.trim() && date && validTime; const sourceName = startMode === 'copy' ? sheets.find((sheet) => sheet.id === sourceSheetId)?.name : templates.find((template) => template.id === templateId)?.name
  return <CtaModal title="Create composition sheet" eyebrow={`Step ${step} of 3 · Workbook setup`} onClose={onClose} wide><div className="cta-wizard-steps"><span className={step >= 1 ? 'active' : ''}>1. Basics</span><span className={step >= 2 ? 'active' : ''}>2. Starting layout</span><span className={step >= 3 ? 'active' : ''}>3. Review</span></div>{step === 1 && <div className="cta-wizard-pane"><p className="cta-wizard-lede">Name the event and set the time members will see. Every time is stored in UTC.</p><div className="form-grid"><label>CTA or event name<input autoFocus value={ctaName} onChange={(event) => setCtaName(event.target.value)} placeholder="e.g. Avalonian Roads CTA" /></label><label>Sheet name<input value={name} onChange={(event) => setName(event.target.value)} placeholder="e.g. Main Zerg" /></label><label>Date (UTC)<input type="date" value={date} onChange={(event) => setDate(event.target.value)} /></label><label>Start time (UTC · 24-hour)<input inputMode="numeric" maxLength="5" value={time} onChange={(event) => setTime(event.target.value.replace(/[^0-9:]/g, '').slice(0, 5))} placeholder="20:00" /></label><label>First party name<input value={party} onChange={(event) => setParty(event.target.value)} placeholder="Party 1" /></label><label>Initial status<select value={status} onChange={(event) => setStatus(event.target.value)}><option value="draft">Draft · private setup</option><option value="open">Open · members can sign up</option></select></label><label>Disarray level<input type="number" min="0" max="8" value={disarray} onChange={(event) => setDisarray(event.target.value)} placeholder="Optional" /></label><label>Recommended group size<input type="number" min="1" value={groupSize} onChange={(event) => setGroupSize(event.target.value)} placeholder="Optional" /></label></div></div>}{step === 2 && <div className="cta-wizard-pane"><p className="cta-wizard-lede">Choose how the rows should start. You can edit every cell after the sheet is created.</p><div className="cta-start-options"><button type="button" className={startMode === 'blank' ? 'selected' : ''} onClick={() => setStartMode('blank')}><span className="cta-start-icon"><CtaIcon name="plus" size={19} /></span><strong>Blank workbook</strong><small>Start with your first party and add rows as you go.</small></button><button type="button" className={startMode === 'copy' ? 'selected' : ''} disabled={!sheets.length} onClick={() => setStartMode('copy')}><span className="cta-start-icon"><CtaIcon name="copy" size={19} /></span><strong>Copy an existing sheet</strong><small>Reuse parties, role slots, and gear requirements.</small>{sheets.length ? <select value={sourceSheetId} onChange={(event) => { setSourceSheetId(event.target.value); setStartMode('copy') }} onClick={(event) => event.stopPropagation()}>{sheets.map((sheet) => <option key={sheet.id} value={sheet.id}>{sheet.ctaName} · {sheet.name}</option>)}</select> : <em>No existing sheets yet</em>}</button><button type="button" className={startMode === 'template' ? 'selected' : ''} disabled={!templates.length} onClick={() => setStartMode('template')}><span className="cta-start-icon"><CtaIcon name="box" size={19} /></span><strong>Saved template</strong><small>Start from a reusable composition layout.</small>{templates.length ? <select value={templateId} onChange={(event) => { setTemplateId(event.target.value); setStartMode('template') }} onClick={(event) => event.stopPropagation()}>{templates.map((template) => <option key={template.id} value={template.id}>{template.name}</option>)}</select> : <em>Save a sheet as a template first</em>}</button></div></div>}{step === 3 && <div className="cta-wizard-pane"><p className="cta-wizard-lede">Review the workbook before creating it.</p><div className="cta-review-card"><div><span>CTA</span><strong>{ctaName || 'Unnamed CTA'}</strong></div><div><span>Sheet</span><strong>{name || 'Unnamed sheet'}</strong></div><div><span>When</span><strong>{date} · {time} UTC</strong></div><div><span>Starting layout</span><strong>{startMode === 'blank' ? 'Blank workbook' : `${startMode === 'copy' ? 'Copy' : 'Template'} · ${sourceName || 'Not selected'}`}</strong></div><div><span>Members</span><strong>{status === 'open' ? 'Can claim empty slots immediately' : 'Wait until the sheet is opened'}</strong></div></div><div className="kit-callout"><CtaIcon name="check" size={18} /><div><strong>Spreadsheet-ready</strong><span>Parties become section rows and every role becomes an exact selectable slot.</span></div></div></div>}<div className="modal-footer"><button type="button" className="button button-ghost" onClick={step === 1 ? onClose : () => setStep((current) => current - 1)}>{step === 1 ? 'Cancel' : 'Back'}</button><span className="modal-footer-spacer" />{step < 3 ? <button type="button" className="button button-primary" disabled={step === 1 && !canContinue} onClick={() => setStep((current) => current + 1)}>Continue <CtaIcon name="arrow" size={15} /></button> : <button type="button" className="button button-primary" disabled={!canContinue} onClick={() => onSave({ ctaName: ctaName.trim(), name: name.trim(), startsAt: ctaStartsAt(date, time), initialPartyName: party.trim() || 'Party 1', status, disarrayLevel: disarray, recommendedGroupSize: groupSize, startMode, sourceSheetId, templateId })}><CtaIcon name="check" size={15} />Create workbook</button>}</div></CtaModal>
}

function CtaSheetEditor({ sheet, activity = [], shareUrl, onSave, onRegenerateLink, onCopyLink, onDuplicate, onSaveTemplate, onAddParty, onRenameParty, onDeleteParty, onAddSlot, onBulkAdd, onUpdateSlot, onDeleteSlot, onUpdateSignup, onDeleteSignup }) {
  const parts = ctaDateTimeParts(sheet.startsAt); const [name, setName] = useState(sheet.name); const [ctaName, setCtaName] = useState(sheet.ctaName); const [date, setDate] = useState(parts.date); const [time, setTime] = useState(parts.time); const [status, setStatus] = useState(sheet.status); const [disarray, setDisarray] = useState(sheet.disarrayLevel); const [groupSize, setGroupSize] = useState(sheet.recommendedGroupSize); const [query, setQuery] = useState(''); const [partyFilter, setPartyFilter] = useState('all'); const [viewFilter, setViewFilter] = useState('all'); const [partyModal, setPartyModal] = useState(false); const [bulkModal, setBulkModal] = useState(null); const validTime = /^([01]\d|2[0-3]):[0-5]\d$/.test(time); const allSlots = sheet.parties.flatMap((party) => party.slots); const filled = allSlots.filter((slot) => slot.signup).length; const locked = status === 'locked'
  useEffect(() => { const next = ctaDateTimeParts(sheet.startsAt); setName(sheet.name); setCtaName(sheet.ctaName); setDate(next.date); setTime(next.time); setStatus(sheet.status); setDisarray(sheet.disarrayLevel); setGroupSize(sheet.recommendedGroupSize) }, [sheet.id, sheet.startsAt, sheet.name, sheet.ctaName, sheet.status, sheet.disarrayLevel, sheet.recommendedGroupSize])
  const save = () => { if (validTime) onSave({ name: name.trim(), ctaName: ctaName.trim(), startsAt: ctaStartsAt(date, time), status, disarrayLevel: disarray, recommendedGroupSize: groupSize }) }
  const matches = (slot) => { const clean = query.trim().toLowerCase(); const text = [slot.slotNumber, slot.roleLabel, slot.classification, slot.signup?.memberName, slot.weapon, slot.offHand, slot.helmet, slot.armor, slot.boots, slot.cape, slot.food, slot.potion, slot.notes].filter(Boolean).join(' ').toLowerCase(); return (!clean || text.includes(clean)) && (partyFilter === 'all' || slot.partyId === partyFilter) && (viewFilter === 'all' || (viewFilter === 'open' && !slot.signup) || (viewFilter === 'filled' && slot.signup) || (viewFilter === 'attendance' && slot.signup && slot.signup.attendanceStatus !== 'signed_up')) }
  const visibleParties = sheet.parties.map((party) => ({ ...party, slots: party.slots.filter(matches) }))
  return <section className="cta-sheet-editor"><div className="cta-sheet-editor-top"><div><span className="eyebrow">Workbook · {ctaUtcLabel(sheet.startsAt)}</span><h2>{sheet.ctaName}</h2><p>{sheet.name} · {filled}/{allSlots.length} filled · {allSlots.length - filled} open slots</p></div><div className="cta-editor-actions"><button type="button" className="button button-ghost" onClick={onDuplicate}><CtaIcon name="copy" size={14} />Duplicate</button><button type="button" className="button button-ghost" onClick={onSaveTemplate}><CtaIcon name="box" size={14} />Save template</button></div></div><div className="cta-sheet-command-bar"><div className="cta-sheet-command-status"><CtaStatus status={status} /><span>{locked ? 'Members can view the grid, but signups are closed.' : status === 'draft' ? 'Private setup mode.' : 'Members can claim empty slots.'}</span></div><div className="cta-sheet-command-actions"><button type="button" className="button button-ghost" onClick={onRegenerateLink}>Regenerate link</button><button type="button" className="button button-primary" onClick={onCopyLink}>Copy public link</button></div></div><div className="cta-share-line"><span>Member link</span><code>{shareUrl || 'Regenerate the link to reveal the public URL.'}</code></div><div className="cta-sheet-settings-strip"><div className="cta-sheet-setting-fields"><label>CTA<input value={ctaName} onChange={(event) => setCtaName(event.target.value)} /></label><label>Sheet<input value={name} onChange={(event) => setName(event.target.value)} /></label><label>Date (UTC)<input type="date" value={date} onChange={(event) => setDate(event.target.value)} /></label><label>Time (UTC)<input inputMode="numeric" maxLength="5" value={time} onChange={(event) => setTime(event.target.value.replace(/[^0-9:]/g, '').slice(0, 5))} /></label><label>Status<select value={status} onChange={(event) => setStatus(event.target.value)}><option value="draft">Draft</option><option value="open">Open</option><option value="locked">Locked</option></select></label><label>Disarray<input type="number" min="0" max="8" value={disarray} onChange={(event) => setDisarray(event.target.value)} placeholder="—" /></label><label>Group size<input type="number" min="1" value={groupSize} onChange={(event) => setGroupSize(event.target.value)} placeholder="—" /></label></div><button type="button" className="button button-primary cta-save-settings" disabled={!ctaName.trim() || !name.trim() || !date || !validTime} onClick={save}><CtaIcon name="check" size={14} />Save</button></div><div className="cta-grid-toolbar"><div className="cta-grid-toolbar-title"><span className="eyebrow">Live roster grid</span><strong>{filled}/{allSlots.length} filled</strong></div><div className="cta-grid-tools"><label className="cta-grid-search"><CtaIcon name="search" size={15} /><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Find IGN, role, or item" aria-label="Find IGN, role, or item" /></label><label className="cta-grid-select"><CtaIcon name="filter" size={14} /><select value={partyFilter} onChange={(event) => setPartyFilter(event.target.value)} aria-label="Filter by party"><option value="all">All parties</option>{sheet.parties.map((party) => <option key={party.id} value={party.id}>{party.name}</option>)}</select></label><select value={viewFilter} onChange={(event) => setViewFilter(event.target.value)} aria-label="Filter slots"><option value="all">All slots</option><option value="open">Open slots</option><option value="filled">Filled slots</option><option value="attendance">Attendance marked</option></select></div></div><div className="cta-grid-actions"><button type="button" className="button button-ghost" disabled={locked} onClick={() => setPartyModal(true)}><CtaIcon name="plus" size={14} />Add party</button><span className="cta-grid-actions-help">Click any gear, role, or slot cell to edit it. Press Enter to save.</span></div><CtaAdminGrid parties={visibleParties} locked={locked} onAddSlot={(partyId) => { const party = sheet.parties.find((entry) => entry.id === partyId); const slotNumber = Math.max(0, ...(party?.slots || []).map((slot) => Number(slot.slotNumber) || 0)) + 1; onAddSlot(partyId, { slotNumber, classification: 'DPS', roleLabel: 'DPS' }) }} onRenameParty={onRenameParty} onDeleteParty={onDeleteParty} onUpdateSlot={onUpdateSlot} onDeleteSlot={onDeleteSlot} onUpdateSignup={onUpdateSignup} onDeleteSignup={onDeleteSignup} />{!visibleParties.length && <div className="cta-grid-empty"><CtaIcon name="search" size={21} /><strong>No matching rows</strong><span>Try another filter or search term.</span></div>}<div className="cta-editor-lower"><CtaActivityPanel activity={activity} /><div className="cta-sheet-guide"><span className="eyebrow">Quick guide</span><strong>Build → Open → Lock</strong><p>Set up role rows, copy the member link when ready, then lock the workbook before the CTA starts.</p></div></div>{partyModal && <CtaPartyModal onClose={() => setPartyModal(false)} onSave={(value) => { onAddParty(value); setPartyModal(false) }} />}{bulkModal && <CtaBulkSlotModal onClose={() => setBulkModal(null)} onSave={(draft, count) => { onBulkAdd(bulkModal.partyId, draft, count); setBulkModal(null) }} />}</section>
}

function CtaAdminGrid({ parties, locked, onAddSlot, onRenameParty, onDeleteParty, onUpdateSlot, onDeleteSlot, onUpdateSignup, onDeleteSignup }) { const [partyId, setPartyId] = useState(parties[0]?.id || ''); useEffect(() => { if (!parties.some((party) => party.id === partyId)) setPartyId(parties[0]?.id || '') }, [parties, partyId]); const selectedParty = parties.find((party) => party.id === partyId); return <><div className="cta-party-action-bar"><label>Party<select value={partyId} onChange={(event) => setPartyId(event.target.value)} aria-label="Choose party to manage"><option value="">Choose party</option>{parties.map((party) => <option key={party.id} value={party.id}>{party.name}</option>)}</select></label><button type="button" className="text-button" disabled={!selectedParty || locked} onClick={() => { const next = window.prompt('Party name', selectedParty?.name || ''); if (next?.trim() && selectedParty) onRenameParty(selectedParty.id, next.trim()) }}><CtaIcon name="edit" size={14} />Rename</button><button type="button" className="text-button danger-text" disabled={!selectedParty || locked} onClick={() => { if (selectedParty && window.confirm('Remove ' + selectedParty.name + ' and all its slots?')) onDeleteParty(selectedParty.id) }}><CtaIcon name="trash" size={14} />Delete</button><button type="button" className="button button-ghost table-add-button" disabled={!selectedParty || locked} onClick={() => selectedParty && onAddSlot(selectedParty.id)}><CtaIcon name="plus" size={14} />Add row</button></div><div className="cta-grid-scroll"><table className="cta-data-grid"><colgroup><col className="cta-col-slot" /><col className="cta-col-class" /><col className="cta-col-role" /><col className="cta-col-member" /><col className="cta-col-attendance" />{gearFields.map(([field]) => <col key={field} className={`cta-col-${field}`} />)}<col className="cta-col-notes" /><col className="cta-col-actions" /></colgroup><thead><tr><th className="sticky-col sticky-col-1">Slot</th><th className="sticky-col sticky-col-2">Class</th><th className="sticky-col sticky-col-3">Role</th><th className="sticky-col sticky-col-4">Member IGN</th><th>Attendance</th>{gearFields.map(([, label]) => <th key={label}>{label}</th>)}<th>Notes</th><th aria-label="Actions" /></tr></thead><tbody>{parties.map((party) => <React.Fragment key={party.id}><tr className="cta-party-row"><th colSpan={5 + gearFields.length + 2}><div className="cta-party-row-title"><span><strong>{party.name}</strong><small>{party.slots.filter((slot) => slot.signup).length}/{party.slots.length} filled</small></span><span className="cta-party-row-actions"><button type="button" className="text-button" onClick={() => { const next = window.prompt('Party name', party.name); if (next?.trim()) onRenameParty(party.id, next.trim()) }} disabled={locked}><CtaIcon name="edit" size={13} />Rename</button><button type="button" className="text-button danger-text" onClick={() => { if (window.confirm(`Remove ${party.name} and all its slots?`)) onDeleteParty(party.id) }} disabled={locked}><CtaIcon name="trash" size={13} />Delete</button><button type="button" className="button button-ghost table-add-button" onClick={() => onAddSlot(party.id)} disabled={locked}><CtaIcon name="plus" size={13} />Add rows</button></span></div></th></tr>{party.slots.map((slot) => <CtaAdminRow key={slot.id} slot={slot} locked={locked} onUpdateSlot={onUpdateSlot} onDeleteSlot={onDeleteSlot} onUpdateSignup={onUpdateSignup} onDeleteSignup={onDeleteSignup} />)}</React.Fragment>)}</tbody></table></div></>}
function CtaAdminRow({ slot, locked, onUpdateSlot, onDeleteSlot, onUpdateSignup, onDeleteSignup }) { const commit = (field, value) => onUpdateSlot(slot.id, buildSlotDraft(slot, field, value)); return <tr className={ctaRowClass(slot)}><td className="sticky-col sticky-col-1"><CtaEditableCell value={slot.slotNumber} type="number" disabled={locked} onCommit={(value) => commit('slotNumber', value)} ariaLabel={`Slot number ${slot.slotNumber}`} /></td><td className="sticky-col sticky-col-2"><select className="cta-grid-cell-select" value={slot.classification} disabled={locked} onChange={(event) => commit('classification', event.target.value)} aria-label={`Classification for slot ${slot.slotNumber}`}>{ctaClassifications.map((option) => <option key={option}>{option}</option>)}</select></td><td className="sticky-col sticky-col-3"><CtaEditableCell value={slot.roleLabel} placeholder="Role label" disabled={locked} onCommit={(value) => commit('roleLabel', value)} ariaLabel={`Role for slot ${slot.slotNumber}`} /></td><td className="sticky-col sticky-col-4"><div className="cta-grid-member">{slot.signup ? <><span className="cta-grid-avatar">{slot.signup.memberName?.[0]?.toUpperCase() || '?'}</span><strong>{slot.signup.memberName}</strong></> : <span className="cta-grid-empty-value">Empty slot</span>}</div></td><td>{slot.signup ? <div className="cta-attendance-cell"><select className="cta-grid-cell-select" value={slot.signup.attendanceStatus} disabled={locked} onChange={(event) => onUpdateSignup(slot.signup.id, { slotId: slot.id, attendanceStatus: event.target.value })} aria-label={`Attendance for ${slot.signup.memberName}`}>{ctaAttendanceStatuses.map((option) => <option key={option} value={option}>{ctaAttendanceLabel(option)}</option>)}</select><button type="button" className="cta-grid-remove" disabled={locked} onClick={() => { if (window.confirm(`Remove ${slot.signup.memberName} from this slot?`)) onDeleteSignup(slot.signup.id) }} aria-label={`Remove ${slot.signup.memberName}`} title="Remove signup">×</button></div> : <span className="cta-grid-dash">—</span>}</td>{gearFields.map(([field]) => <td key={field}><CtaEditableCell value={slot[field]} placeholder="Add item" disabled={locked} onCommit={(value) => commit(field, value)} ariaLabel={`${field} for slot ${slot.slotNumber}`} /></td>)}<td><CtaEditableCell value={slot.notes} placeholder="Add note" disabled={locked} onCommit={(value) => commit('notes', value)} ariaLabel={`Notes for slot ${slot.slotNumber}`} /></td><td><button type="button" className="cta-grid-delete" disabled={locked} onClick={() => { if (window.confirm(`Remove slot ${slot.slotNumber}?`)) onDeleteSlot(slot.id) }} aria-label={`Delete slot ${slot.slotNumber}`} title="Delete slot"><CtaIcon name="trash" size={14} /></button></td></tr> }
function CtaEditableCell({ value, placeholder, onCommit, disabled, type = 'text', ariaLabel }) { const [editing, setEditing] = useState(false); const [draft, setDraft] = useState(value ?? ''); useEffect(() => { if (!editing) setDraft(value ?? '') }, [value, editing]); const commit = () => { setEditing(false); if (String(draft) !== String(value ?? '')) onCommit(draft) }; if (editing) return <input className="cta-grid-cell-input" type={type} autoFocus value={draft} onChange={(event) => setDraft(event.target.value)} onBlur={commit} onKeyDown={(event) => { if (event.key === 'Enter') { event.preventDefault(); commit() } if (event.key === 'Escape') { setDraft(value ?? ''); setEditing(false) } }} aria-label={ariaLabel} />; return <button type="button" className={`cta-grid-cell-button ${!value ? 'empty' : ''}`} disabled={disabled} onClick={() => setEditing(true)} title={disabled ? undefined : 'Click to edit'}>{value || placeholder || '—'}</button> }
function CtaActivityPanel({ activity = [] }) { return <details className="cta-activity-panel" open><summary><span><span className="eyebrow">Audit trail</span><strong>Sheet activity</strong></span><small>{activity.length} entries</small></summary><div className="cta-activity-list">{activity.slice(0, 18).map((entry) => <div className="cta-activity-item" key={entry.id}><span className="cta-activity-dot" /><div><strong>{entry.action}</strong><span>{entry.actor_name || entry.actorName || 'Administrator'}</span></div><time>{formatActivityTime(entry.created_at || entry.createdAt)}</time></div>)}{!activity.length && <p>No changes recorded yet.</p>}</div></details> }
function CtaPartyModal({ onClose, onSave }) { const [name, setName] = useState(''); return <CtaModal title="Add party" eyebrow="Workbook structure" onClose={onClose}><label>Party name<input autoFocus value={name} onChange={(event) => setName(event.target.value)} placeholder="e.g. Party 2" /></label><div className="modal-footer"><button type="button" className="button button-ghost" onClick={onClose}>Cancel</button><button type="button" className="button button-primary" disabled={!name.trim()} onClick={() => onSave(name.trim())}><CtaIcon name="plus" size={15} />Add party</button></div></CtaModal> }
function CtaBulkSlotModal({ onClose, onSave }) { const [classification, setClassification] = useState('DPS'); const [roleLabel, setRoleLabel] = useState('DPS'); const [count, setCount] = useState(5); const [startNumber, setStartNumber] = useState(1); return <CtaModal title="Add multiple rows" eyebrow="Fast composition setup" onClose={onClose}><p className="cta-modal-intro">Create repeated positions first, then fill gear requirements directly in the grid.</p><div className="form-grid"><label>Number of rows<input type="number" min="1" max="50" value={count} onChange={(event) => setCount(Math.min(50, Math.max(1, Number(event.target.value) || 1)))} /></label><label>Start slot number<input type="number" min="1" value={startNumber} onChange={(event) => setStartNumber(Number(event.target.value) || 1)} /></label><label>Classification<select value={classification} onChange={(event) => { setClassification(event.target.value); setRoleLabel(event.target.value) }}>{ctaClassifications.map((option) => <option key={option}>{option}</option>)}</select></label><label>Role label<input value={roleLabel} onChange={(event) => setRoleLabel(event.target.value)} placeholder="e.g. Brawl DPS" /></label></div><div className="modal-footer"><button type="button" className="button button-ghost" onClick={onClose}>Cancel</button><button type="button" className="button button-primary" onClick={() => onSave({ classification, roleLabel: roleLabel.trim() || classification, startNumber }, count)}><CtaIcon name="plus" size={15} />Add {count} rows</button></div></CtaModal> }

export function PublicCtaSheet({ token }) {
  const [sheet, setSheet] = useState(null); const [loading, setLoading] = useState(true); const [error, setError] = useState(''); const [partyId, setPartyId] = useState('all'); const [classification, setClassification] = useState('All roles'); const [viewFilter, setViewFilter] = useState('all'); const [query, setQuery] = useState(''); const [signupSlot, setSignupSlot] = useState(null); const [manageSlot, setManageSlot] = useState(null); const [receipt, setReceipt] = useState(''); const [editSession, setEditSession] = useState(() => { try { return JSON.parse(window.localStorage.getItem(`cta-edit-${token}`) || 'null') } catch { return null } })
  const refresh = async () => { try { const next = await loadPublicCtaSheet(token); setSheet(next); setError('') } catch (loadError) { setError(loadError.message || 'Could not load this CTA sheet.') } finally { setLoading(false) } }
  useEffect(() => { let mounted = true; const run = async () => { try { const next = await loadPublicCtaSheet(token); if (mounted) { setSheet(next); setError('') } } catch (loadError) { if (mounted) setError(loadError.message || 'Could not load this CTA sheet.') } finally { if (mounted) setLoading(false) } }; run(); const interval = window.setInterval(() => { if (mounted) refresh() }, 10000); return () => { mounted = false; window.clearInterval(interval) } }, [token])
  if (loading) return <div className="public-cta-shell"><div className="public-cta-loading"><div className="public-loader" /><span>Loading composition workbook...</span></div></div>
  if (error || !sheet) return <div className="public-cta-shell"><div className="public-cta-error"><div className="brand-mark">A<span>R</span></div><span className="eyebrow">Coup De Grace CTA Sheets</span><h1>Sheet unavailable.</h1><p>{error || 'This CTA composition could not be found.'}</p><button type="button" className="button button-primary" onClick={refresh}>Try again</button></div></div>
  const allSlots = sheet.parties.flatMap((party) => party.slots); const visibleParties = sheet.parties.map((party) => ({ ...party, slots: party.slots.filter((slot) => { const clean = query.trim().toLowerCase(); const text = [slot.slotNumber, slot.roleLabel, slot.classification, slot.signup?.memberName, slot.weapon, slot.offHand, slot.helmet, slot.armor, slot.boots, slot.cape, slot.food, slot.potion, slot.notes].filter(Boolean).join(' ').toLowerCase(); return (!clean || text.includes(clean)) && (partyId === 'all' || party.id === partyId) && (classification === 'All roles' || slot.classification === classification) && (viewFilter === 'all' || (viewFilter === 'open' && !slot.signup) || (viewFilter === 'filled' && slot.signup)) }) })).filter((party) => party.slots.length); const filled = allSlots.filter((slot) => slot.signup).length
  const claim = async (memberId, slotId) => { const result = await submitPublicCtaAction(token, { action: 'claim', memberId, slotId }); const nextSession = { signupId: result.signup.id, editCode: result.editCode }; window.localStorage.setItem(`cta-edit-${token}`, JSON.stringify(nextSession)); setEditSession(nextSession); setSignupSlot(null); setReceipt(result.editCode); await refresh() }
  const manage = async (action, slotId) => { await submitPublicCtaAction(token, { action, signupId: editSession.signupId, editCode: editSession.editCode, slotId }); if (action === 'release') { window.localStorage.removeItem(`cta-edit-${token}`); setEditSession(null) } setManageSlot(null); await refresh() }
  return <div className="public-cta-shell"><header className="public-cta-header"><div className="public-cta-brand"><div className="brand-mark">A<span>R</span></div><div><span className="eyebrow">Coup De Grace</span><strong>CTA composition workbook</strong></div></div><div className="public-cta-live"><i /> Auto-refreshing</div></header><main className="public-cta-main"><section className="public-cta-hero"><div><span className="eyebrow">{sheet.status === 'locked' ? 'Signups locked' : sheet.status === 'draft' ? 'Admin preview' : 'Signups open'} · UTC</span><h1>{sheet.ctaName}</h1><p>{sheet.name} · {ctaUtcLabel(sheet.startsAt)}</p></div><div className="public-cta-hero-stats"><strong>{filled}/{allSlots.length}</strong><span>slots filled</span>{sheet.disarrayLevel && <small>Disarray {sheet.disarrayLevel}{sheet.recommendedGroupSize ? ` · Group ${sheet.recommendedGroupSize}` : ''}</small>}</div></section><div className="public-cta-tabs">{sheet.parties.map((party) => <button type="button" className={partyId === party.id ? 'selected' : ''} key={party.id} onClick={() => setPartyId(party.id)}>{party.name}<span>{party.slots.filter((slot) => slot.signup).length}/{party.slots.length}</span></button>)}<button type="button" className={partyId === 'all' ? 'selected' : ''} onClick={() => setPartyId('all')}>All parties</button></div><div className="public-cta-toolbar"><label><CtaIcon name="search" size={15} /><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Find IGN, role, or item" aria-label="Find IGN, role, or item" /></label><select value={classification} onChange={(event) => setClassification(event.target.value)} aria-label="Filter by classification"><option>All roles</option>{ctaClassifications.map((option) => <option key={option}>{option}</option>)}</select><select value={viewFilter} onChange={(event) => setViewFilter(event.target.value)} aria-label="Filter slots"><option value="all">All slots</option><option value="open">Open slots</option><option value="filled">Filled slots</option></select></div><div className="cta-grid-scroll public-cta-grid-scroll"><table className="cta-data-grid public-cta-data-grid"><colgroup><col className="cta-col-slot" /><col className="cta-col-class" /><col className="cta-col-role" /><col className="cta-col-member" /><col className="cta-col-attendance" />{gearFields.map(([field]) => <col key={field} className={`cta-col-${field}`} />)}<col className="cta-col-notes" /></colgroup><thead><tr><th className="sticky-col sticky-col-1">Slot</th><th className="sticky-col sticky-col-2">Class</th><th className="sticky-col sticky-col-3">Role</th><th className="sticky-col sticky-col-4">Member IGN</th><th>Attendance</th>{gearFields.map(([, label]) => <th key={label}>{label}</th>)}<th>Notes</th></tr></thead><tbody>{visibleParties.map((party) => <React.Fragment key={party.id}><tr className="cta-party-row"><th colSpan={5 + gearFields.length + 1}><div className="cta-party-row-title"><span><strong>{party.name}</strong><small>{party.slots.filter((slot) => slot.signup).length}/{party.slots.length} filled</small></span></div></th></tr>{party.slots.map((slot) => <CtaPublicRow key={slot.id} slot={slot} locked={sheet.status === 'locked'} isMine={slot.signup?.id === editSession?.signupId} onClaim={() => setSignupSlot(slot)} onManage={() => setManageSlot(slot)} />)}</React.Fragment>)}</tbody></table></div>{!visibleParties.length && <div className="public-cta-grid-empty"><CtaIcon name="search" size={22} /><strong>No matching rows</strong><span>Try another filter or search term.</span></div>}<footer className="public-cta-footer"><span>Registered Coup De Grace IGNs only</span><span>Updates every 10 seconds · All times UTC</span></footer></main>{signupSlot && <PublicCtaSignupModal sheet={sheet} slot={signupSlot} onClose={() => setSignupSlot(null)} onClaim={claim} />}{manageSlot && editSession && <PublicCtaManageModal sheet={sheet} slot={manageSlot} onClose={() => setManageSlot(null)} onAction={manage} />}{receipt && <CtaModal title="Save your private edit code" eyebrow="Signup confirmed" onClose={() => setReceipt('')}><div className="cta-code-receipt"><span>Your IGN is now in</span><strong>{sheet.name}</strong><code>{receipt}</code><p>Keep this code private. It lets you move or release your own signup while the sheet is unlocked.</p><button type="button" className="button button-primary" onClick={() => setReceipt('')}>I saved my code</button></div></CtaModal>}</div>
}

function CtaPublicRow({ slot, locked, isMine, onClaim, onManage }) { return <tr className={ctaRowClass(slot, isMine ? 'mine' : '')}><td className="sticky-col sticky-col-1"><span className="cta-grid-number">{slot.slotNumber}</span></td><td className="sticky-col sticky-col-2"><span className="cta-grid-classification">{slot.classification}</span></td><td className="sticky-col sticky-col-3"><strong className="cta-grid-role-value">{slot.roleLabel}</strong></td><td className="sticky-col sticky-col-4"><div className="cta-grid-member">{slot.signup ? <><span className="cta-grid-avatar">{slot.signup.memberName?.[0]?.toUpperCase() || '?'}</span><strong>{slot.signup.memberName}</strong>{isMine && <button type="button" className="text-button" onClick={onManage}>Manage</button>}</> : <button type="button" className="cta-public-claim" disabled={locked} onClick={onClaim}>{locked ? 'Locked' : 'Choose slot'}<CtaIcon name="arrow" size={13} /></button>}</div></td><td>{slot.signup ? <span className={`cta-public-attendance cta-public-attendance-${slot.signup.attendanceStatus}`}>{ctaAttendanceLabel(slot.signup.attendanceStatus)}</span> : <span className="cta-grid-dash">—</span>}</td>{gearFields.map(([field]) => <td key={field}><span className={`cta-grid-read-value ${!slot[field] ? 'empty' : ''}`}>{slot[field] || '—'}</span></td>)}<td><span className="cta-grid-read-value cta-grid-note-value">{slot.notes || '—'}</span></td></tr> }
function PublicCtaSignupModal({ sheet, slot, onClose, onClaim }) { const [query, setQuery] = useState(''); const [member, setMember] = useState(null); const [saving, setSaving] = useState(false); const matches = sheet.members.filter((entry) => entry.name.toLowerCase().includes(query.toLowerCase())).slice(0, 8); const claim = async () => { if (!member) return; setSaving(true); try { await onClaim(member.id, slot.id) } catch (error) { window.alert(error.message || 'Could not claim this slot.') } finally { setSaving(false) } }; return <CtaModal title={`Claim slot ${slot.slotNumber}`} eyebrow={`${slot.roleLabel} · Select your registered IGN`} onClose={onClose}><p className="cta-modal-intro">Choose your existing guild IGN. You are claiming this exact role row.</p><label>Search registered IGN<input autoFocus value={query} onChange={(event) => { setQuery(event.target.value); setMember(null) }} placeholder="Type your character name" /></label><div className="public-member-picker">{matches.map((entry) => <button type="button" className={member?.id === entry.id ? 'selected' : ''} key={entry.id} onClick={() => setMember(entry)}><span className="avatar avatar-teal">{entry.name[0]?.toUpperCase()}</span><strong>{entry.name}</strong>{member?.id === entry.id && <CtaIcon name="check" size={15} />}</button>)}{query && !matches.length && <span>No registered member matches that IGN.</span>}</div><div className="modal-footer"><button type="button" className="button button-ghost" onClick={onClose}>Cancel</button><button type="button" className="button button-primary" disabled={!member || saving} onClick={claim}>{saving ? 'Claiming...' : 'Confirm signup'}</button></div></CtaModal> }
function PublicCtaManageModal({ sheet, slot, onClose, onAction }) { const [target, setTarget] = useState(''); const available = sheet.parties.flatMap((party) => party.slots).filter((candidate) => !candidate.signup && candidate.id !== slot.id); return <CtaModal title={`Manage ${slot.signup?.memberName || 'your signup'}`} eyebrow="Private signup controls" onClose={onClose}><p className="cta-modal-intro">Move to another empty slot or release your signup while the sheet is open.</p><label>Move to another empty slot<select value={target} onChange={(event) => setTarget(event.target.value)}><option value="">Keep current slot</option>{available.map((candidate) => <option key={candidate.id} value={candidate.id}>Slot {candidate.slotNumber} · {candidate.roleLabel}</option>)}</select></label><div className="modal-footer"><button type="button" className="button button-danger" onClick={() => { if (window.confirm('Release your signup from this CTA sheet?')) onAction('release') }}>Release signup</button><span className="modal-footer-spacer" /><button type="button" className="button button-ghost" onClick={onClose}>Cancel</button><button type="button" className="button button-primary" disabled={!target} onClick={() => onAction('move', target)}>Move slot</button></div></CtaModal> }
